<template><div class="page" v-if="s"><button class="back" @click="$router.push(`/analysis/${route.params.id}/scenario/${s.id}`)">← Back to Scenario</button><header class="page-head"><div><div class="eyebrow">WIREFRAME GALLERY</div><h1>{{s.title}}</h1><p>All wireframes for this scenario · {{s.stages.length}} screens</p></div></header><div class="gallery"><article v-for="(x,i) in s.stages" :key="x.id" class="gallery-card"><div class="gallery-img"><img :src="x.imageUrl"/><span>{{i+1}}</span></div><b>{{x.title}}</b><small>{{x.type}}</small></article></div></div></template>
<script setup lang="ts">import{ref,onMounted}from'vue';import{useRoute}from'vue-router';import{api}from'../api';const route=useRoute();const s=ref<any>();onMounted(async()=>{const a=await api.get(route.params.id as string);s.value=a.scenarios.find((x:any)=>x.id===route.params.scenarioId)})</script>
